"use strict";(globalThis.webpackChunkmy_website||=[]).push([[96200],{71112(e){e.exports=JSON.parse('{"slug":"governance-action-lifetime","title":"Governance Action Lifetime","short":"The protocol parameter that caps how many epochs a governance action can stay open for votes before it expires unresolved.","category":"governance","aliases":["govActionLifetime"],"mentalModel":"An expiry date on every governance action. If a proposal does not collect the required votes before the deadline, it lapses and has to be resubmitted to try again.","related":["governance-action","drep","cip-1694","voting-thresholds"],"sources":[],"link":null,"level":"intermediate","body":"If a governance action expires, the action\'s submission deposit is returned to the proposer. The lifetime exists so the protocol does not accumulate an open backlog of stale proposals waiting indefinitely for votes that may never arrive."}')}}]);